package kr.seoulhousing.alerts;
import android.content.Intent; import android.os.Bundle; import androidx.appcompat.app.AppCompatActivity; import androidx.recyclerview.widget.*; import org.json.*; import java.util.*;
public class AnnouncementListActivity extends AppCompatActivity {
    @Override public void onCreate(Bundle state) { super.onCreate(state); setContentView(R.layout.activity_list); ((android.widget.TextView)findViewById(R.id.list_title)).setText("공고 목록"); RecyclerView list=findViewById(R.id.list); list.setLayoutManager(new LinearLayoutManager(this)); ApiClient.request(this,"GET","announcements",null,(json,error)->runOnUiThread(()-> { List<String> labels=new ArrayList<>(),ids=new ArrayList<>(); JSONObject catalog=json==null?new JSONObject():json.optJSONObject("catalog"); JSONArray items=catalog==null?new JSONArray():catalog.optJSONArray("items"); for(int i=0;items!=null&&i<items.length();i++){JSONObject item=items.optJSONObject(i); labels.add(item.optString("title")+"\n"+item.optString("sourceName")+" · "+item.optString("status"));ids.add(item.optString("id"));} list.setAdapter(new TextRowAdapter(labels,ids,id->startActivity(new Intent(this,AnnouncementDetailActivity.class).putExtra("announcementId",id)))); })); }
}
